// src/components/layout/Header.jsx
import React from 'react';

const Header = () => {
  return (
    <header className="bg-white p-4 flex justify-end items-center h-16 border-b border-gray-200 flex-shrink-0">
      <div className="w-10 h-10 bg-gray-100 border border-gray-200 rounded-full flex items-center justify-center">
        {/* A standard user icon is a common and professional choice for this location */}
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
        </svg>
      </div>
    </header>
  );
};

export default Header;
